// SAMPLE Asana department projects (workspace 1211278136475640), pulled live 2026-06-13.
const DEPARTMENTS = [
  { department: 'Human Resources',       projectGid: '1211616183932936' }, // 07 Human Resources & Team Alignment
  { department: 'Marketing',             projectGid: '1211616183932955' }, // 02 Marketing
  { department: 'Offers',                projectGid: '1211616183932967' }, // 03 Offers
  { department: 'Sales',                 projectGid: '1211616183932975' }, // 04 Sales
  { department: 'Client Relations',      projectGid: '1211616183932986' }, // 05 Client Relations
  { department: 'Business Partnerships', projectGid: '1211616183932997' }  // 06 Business Partnerships
];

return DEPARTMENTS.map(d => ({ json: d }));

// Aggregate ALL pages for the CURRENT department. The Loop isolates one dept per
// pass, so every incoming item (page) belongs to the same department. This is
// pagination-proof: 1 page or 50 pages are handled identically.
const dept = $('Loop Over Departments').all()[0].json.department;

let tasks = [];
for (const it of $input.all()) {
  const d = it.json.data;
  if (Array.isArray(d)) tasks = tasks.concat(d);
}

const now    = new Date();
const today  = new Date(now.getFullYear(), now.getMonth(), now.getDate());
const in7    = new Date(today); in7.setDate(in7.getDate() + 7);
const last7  = new Date(today); last7.setDate(last7.getDate() - 7);

let completedLastWeek = 0, overdue = 0, upcoming = 0, totalOpen = 0;

for (const t of tasks) {
  const completed   = !!t.completed;
  const completedAt = t.completed_at ? new Date(t.completed_at) : null;
  const dueOn       = t.due_on ? new Date(t.due_on + 'T00:00:00') : null;

  if (completed) {
    if (completedAt && completedAt >= last7 && completedAt <= now) completedLastWeek++;
  } else {
    totalOpen++;
    if (dueOn && dueOn <  today) overdue++;
    if (dueOn && dueOn >= today && dueOn <= in7) upcoming++;
  }
}

// Monday of the current week as the snapshot date
const wk  = new Date(today);
const dow = wk.getDay();                 // 0=Sun .. 6=Sat
wk.setDate(wk.getDate() + (dow === 0 ? -6 : 1 - dow));
const weekOf = wk.toISOString().slice(0, 10);

return [{ json: {
  'Department':          dept,
  'Week Of':             weekOf,
  'Completed Last Week': completedLastWeek,
  'Overdue':             overdue,
  'Upcoming Next Week':  upcoming,
  'Total Open':          totalOpen,
  'Snapshot Key':        weekOf + '|' + dept
} }];
